insert into disease_passages (disease_name_en, topic, passage_en, source_name, source_url, source_section, verified) values
  ('Sheath blight', 'hosts', 'The sheath blight fungus (Rhizoctonia solani AG1-IA) attacks rice and also other crops such as maize, sorghum, soybean, mungbean and cowpea, and many weeds growing around rice fields, such as Echinochloa spp. and Monochoria sp.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 1 Ch. 3 (leaf sheath and culm diseases), sheath blight', 'https://rice-diseases.irri.org/contents', 'sec. 2.2.3 Host range', false),
  ('Sheath blight', 'survival_spread', 'The fungus survives between crops as sclerotia (resting bodies) and as mycelium in rice stubble and plant debris left in the field. It also survives on other hosts: weeds, ratoon rice, and upland crops such as maize and legumes grown after rice.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 1 Ch. 3 (leaf sheath and culm diseases), sheath blight', 'https://rice-diseases.irri.org/contents', 'sec. 2.2.4.2 Sources of inoculum', false),
  ('Sheath blight', 'survival_spread', 'After a field is flooded, sclerotia float in the paddy water and attach to the base of a plant near the waterline, where they usually cause the first lesions. The fungus then grows upward and sideways, from tiller to tiller and between neighbouring plants, and a new lesion starts where its mycelium touches healthy tissue. The disease attacks all parts of the rice plant except the roots.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 1 Ch. 3 (leaf sheath and culm diseases), sheath blight', 'https://rice-diseases.irri.org/contents', 'sec. 2.2.4.1 and 2.2.5 Infection and spread', false),
  ('Sheath blight', 'survival_spread', 'Under field conditions the fungus can spread very fast, estimated at 20 cm/day on average. Signs of the disease are sclerotia, mycelial strands growing over the lesions, and thin grayish or white powdery layers (hymenia) on leaf sheaths or leaf blades of young plants.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 1 Ch. 3 (leaf sheath and culm diseases), sheath blight', 'https://rice-diseases.irri.org/contents', 'sec. 2.2.1 Symptoms', false),
  ('Sheath blight', 'favouring_conditions', 'Sheath blight gets worse with more nitrogen fertilizer, because nitrogen changes the crop canopy so that leaves touch more and stay wet for longer; leaf wetness matters more than humidity itself. In one study, yield reduction reached 20 to 42% in plots with the highest amount of nitrogen.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 1 Ch. 3 (leaf sheath and culm diseases), sheath blight', 'https://rice-diseases.irri.org/contents', 'sec. 2.2.5 and 2.2.7.1 Nitrogen', false),
  ('Sheath blight', 'favouring_conditions', 'Sheath blight became a major disease after rice growing was intensified with high-yielding semidwarf varieties, high nitrogen and continuous cropping. A given level of disease causes more yield loss where the attainable yield is high. It is also favoured by the shift from transplanted to direct-seeded rice.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 1 Ch. 3 (leaf sheath and culm diseases), sheath blight', 'https://rice-diseases.irri.org/contents', 'sec. 2.1 and 2.2.4 Intensive rice growing', false),
  ('Sheath blight', 'impact', 'In tropical and subtropical Asia, sheath blight causes an average yield loss of about 6%, which is higher than that caused by other rice diseases. In China it causes an annual yield loss of 3 to 4%, equal to 6 million tons. A yield loss of 50% has been reported in plots of highly susceptible varieties in the United States.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 1 Ch. 3 (leaf sheath and culm diseases), sheath blight', 'https://rice-diseases.irri.org/contents', 'sec. 2.2.1 and 2.2.7 Losses', false),
  ('Sheath blight', 'management_cultural', 'To manage sheath blight, avoid excessive nitrogen: apply only the amount the crop needs and the soil does not already supply. Splitting the nitrogen into several applications, instead of applying all of it early in the season, has been recommended.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 1 Ch. 3 (leaf sheath and culm diseases), sheath blight', 'https://rice-diseases.irri.org/contents', 'sec. 2.2.7.1 Nitrogen', false),
  ('Sheath blight', 'management_cultural', 'Field sanitation is one of the most effective ways to reduce sheath blight: remove or destroy infected rice straw and weeds inside the field and on the levees. Burning does not completely destroy sclerotia, so it must be combined with other measures. Ploughing the stubble soon after harvest and speeding up straw decomposition reduce the fungus; Trichoderma harzianum has been used for rapid composting.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 1 Ch. 3 (leaf sheath and culm diseases), sheath blight', 'https://rice-diseases.irri.org/contents', 'sec. 2.2.7.5 Field sanitation', false),
  ('Sheath blight', 'management_cultural', 'Silicon can reduce sheath blight. Sources include calcium silicate slag or cheaper rice hulls or rice straw, and varieties with high silicon content. Plants given silicon had less sheath blight than plants without it.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 1 Ch. 3 (leaf sheath and culm diseases), sheath blight', 'https://rice-diseases.irri.org/contents', 'sec. 2.2.7.2 Application of silicon', false),
  ('Sheath blight', 'management_biological', 'Antagonistic bacteria such as Bacillus subtilis and strains of Pseudomonas fluorescens have been used against sheath blight, most widely in China. Used alone the results were often inconsistent; results were more consistent when Bacillus subtilis was mixed with a half dose of a commercial fungicide (Jingangmycin in China, Validamycin in Vietnam). Many biological control agents have not been tested in the field or are not yet commercially available.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 1 Ch. 3 (leaf sheath and culm diseases), sheath blight', 'https://rice-diseases.irri.org/contents', 'sec. 2.2.7.3 Biological control', false),
  ('Sheath blight', 'management_resistance', 'No commercial rice variety is known to be resistant to sheath blight. The best available are varieties that are less susceptible. Managing sheath blight with resistant varieties has not been promoted the way it has for blast.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 1 Ch. 3 (leaf sheath and culm diseases), sheath blight', 'https://rice-diseases.irri.org/contents', 'sec. 2.2.7 Disease management', false),
  ('Sheath blight', 'management_chemical', 'Fungicides are commonly used against sheath blight in Japan, Korea, China and Vietnam, but not widely in other Asian countries because they are not available in local markets and are not economically feasible for resource-poor farmers. Reported effective fungicides are azoxystrobin, flutolanil, pencycuron, hexaconazole and propiconazole; validamycin, an antibiotic, is widely used. They worked best when applied at the booting and heading stages; application after heading was less effective.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 1 Ch. 3 (leaf sheath and culm diseases), sheath blight', 'https://rice-diseases.irri.org/contents', 'sec. 2.2.7.4 Chemical control', false),
  ('Tungro', 'survival_spread', 'Tungro is not spread by touch, by seed, or through the soil. It is carried from plant to plant by leafhoppers. The main carrier is the green leafhopper; other leafhoppers (Nephotettix nigropictus, N. cincticeps, N. malayanus, N. parvus and the zig-zag leafhopper Recilia dorsalis) can also carry it.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 3 Ch. 1 (leafhopper-borne virus diseases), rice tungro', 'https://rice-diseases.irri.org/contents', 'sec. 5.5 Transmission by vectors', false),
  ('Tungro', 'survival_spread', 'A green leafhopper can pick up the tungro viruses after feeding only 10 to 30 minutes on an infected plant and can pass them on soon afterwards. It usually keeps the ability for 2 or 3 days (up to 5 or 6 days), longer at lower temperatures. It loses the ability after molting but can pick the viruses up again.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 3 Ch. 1 (leafhopper-borne virus diseases), rice tungro', 'https://rice-diseases.irri.org/contents', 'sec. 5.5 Transmission by vectors', false),
  ('Tungro', 'survival_spread', 'The green leafhopper feeds almost only on rice and can have 9 to 12 generations a year if rice is available. When there is no rice it feeds on several wild rice species and grassy weeds.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 3 Ch. 1 (leafhopper-borne virus diseases), rice tungro', 'https://rice-diseases.irri.org/contents', 'sec. 5.7.1 Vector biology and ecology', false),
  ('Tungro', 'favouring_conditions', 'Tungro is generally endemic and often reaches epidemic levels in irrigated areas where rice planting is staggered and rice is present throughout the year. Where planting is roughly synchronized in one or two seasons a year with fallow periods in between, tungro is scarce or absent in many years, although it may reach epidemic levels about once in a decade. In rainfed and upland rice it is absent, except in years of widespread outbreaks.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 3 Ch. 1 (leafhopper-borne virus diseases), rice tungro', 'https://rice-diseases.irri.org/contents', 'sec. 5.7 Disease cycle and epidemiology', false),
  ('Tungro', 'favouring_conditions', 'Tungro is generally higher in the rainy season than in the dry season, higher in fields planted when leafhopper numbers are high, and higher in fields planted late in the crop season. Applying nitrogen fertilizer was reported to increase tungro, and extra nitrogen did not help reduce it.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 3 Ch. 1 (leafhopper-borne virus diseases), rice tungro', 'https://rice-diseases.irri.org/contents', 'sec. 5.10.2 Cultivation practices', false),
  ('Tungro', 'impact', 'Major tungro outbreaks have repeatedly caused serious damage in Bangladesh, India, Indonesia, Malaysia, the Philippines, Thailand and Vietnam. In the 1980s, average annual losses from tungro were estimated to exceed USD 1,500 million.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 3 Ch. 1 (leafhopper-borne virus diseases), rice tungro', 'https://rice-diseases.irri.org/contents', 'sec. 5.8 Losses', false),
  ('Tungro', 'management_cultural', 'Seedlings 3 or 4 weeks old are suitable for tungro management; planting old seedlings increased infection in seedbeds and in the transplanted fields. Seedlings rarely showed tungro symptoms in nursery beds at 25 days after sowing but more often at 45 days.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 3 Ch. 1 (leafhopper-borne virus diseases), rice tungro', 'https://rice-diseases.irri.org/contents', 'sec. 5.10.2 Cultivation practices', false),
  ('Tungro', 'management_cultural', 'Field sanitation is an important measure against tungro. Ploughing, and mowing weeds or applying herbicide in and around the fields during the fallow period, reduce leafhoppers and sources of the disease. Dry ploughing during the fallow period reduced leafhopper numbers and infected rice stubble and grass.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 3 Ch. 1 (leafhopper-borne virus diseases), rice tungro', 'https://rice-diseases.irri.org/contents', 'sec. 5.10.2 Cultivation practices', false),
  ('Tungro', 'management_cultural', 'Planting fields in an area at about the same time, with a fallow period of 1 month or more between crops, has been used successfully against tungro in Indonesia and Malaysia. The scheme in South Sulawesi also planted when leafhopper numbers were low, rotated varieties with different resistance, and treated affected fields to stop the spread to nearby fields. Tungro was generally low in areas that followed the scheme.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 3 Ch. 1 (leafhopper-borne virus diseases), rice tungro', 'https://rice-diseases.irri.org/contents', 'sec. 5.10.3 Synchrony in planting', false),
  ('Tungro', 'management_resistance', 'Resistant varieties are the most efficient and economical control measure for tungro and have played a critical role in managing it, especially in irrigated areas of South and Southeast Asia. Many varieties have been identified as resistant or tolerant.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 3 Ch. 1 (leafhopper-borne virus diseases), rice tungro', 'https://rice-diseases.irri.org/contents', 'sec. 5.9.1 Cultivar resistance', false),
  ('Tungro', 'management_chemical', 'No chemical works against the tungro viruses themselves, so insecticides are used to reduce the leafhoppers that carry them; they are applied against tungro spread, not because leafhoppers damage the plants by feeding. In a trial, applying a knockdown compound together with an insectistatic compound at 2 and 16 days after transplanting gave efficient control, while applying in the nursery beds had little effect.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 3 Ch. 1 (leafhopper-borne virus diseases), rice tungro', 'https://rice-diseases.irri.org/contents', 'sec. 5.10.1 Chemical control', false),
  ('Tungro', 'management_chemical', 'Insecticide sprays on the leaves were often ineffective because monsoon rain washed them off, so they worked less well in the wet season, when tungro is generally higher. Spraying early in the crop, if done improperly, can cause brown planthopper numbers to build up. In the Philippines one insecticide became less effective against tungro because the leafhoppers developed resistance to it.', 'IRRI, Rice Diseases: Biology & Selected Management Practices (2018), Section 3 Ch. 1 (leafhopper-borne virus diseases), rice tungro', 'https://rice-diseases.irri.org/contents', 'sec. 5.10.1 Chemical control', false),
  ('Blast', 'identification', 'Blast spots on leaves are oval or diamond-shaped, 5-15 mm long and 3-5 mm wide, with dark borders and often a yellow halo. As spots age the centre turns whitish-grey and the border becomes wider and red-brown. Spots join together, leaves die, and a field can look scorched.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice blast, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_blast_252.htm', 'Symptoms & Life Cycle', false),
  ('Blast', 'identification', 'The spores also infect the leaf sheath, stem and panicle and cause: collar rot (kills the leaf); neck rot (rotten neck, whiteheads); panicle rot (brown or black branches); and node rot (black-brown and dry; the plant dies if the stem breaks).', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice blast, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_blast_252.htm', 'Symptoms & Life Cycle', false),
  ('Blast', 'favouring_conditions', 'Frequent, prolonged showers and temperatures of 24-28 C favour blast. Leaves must stay wet for 6-8 hours for spores to germinate and the humidity must be close to 100%. In upland areas dew from day and night temperature differences also favours it. In lowland fields leaf infection is lower, but blast is serious in seedling nurseries and on panicles.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice blast, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_blast_252.htm', 'Symptoms & Life Cycle', false),
  ('Blast', 'survival_spread', 'Blast spreads in irrigation water, and spores are carried short and long distances by air currents and wind. Between crops the fungus survives in straw and stubble, in seed, in volunteer rice, and on alternative grass hosts.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice blast, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_blast_252.htm', 'Symptoms & Life Cycle', false),
  ('Blast', 'impact', 'Blast is a major disease of rice. It can kill plants up to tillering or reduce grain yield and quality. Rice grown all year round gives the potential for major epidemics, and the impact is less where rice is rotated with root crops or intercropped with sorghum, maize, cassava or vegetables.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice blast, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_blast_252.htm', 'Impact', false),
  ('Blast', 'management_cultural', 'Blast management uses an integrated (IPM) approach: tolerant or resistant varieties, splitting nitrogen into two or three applications, acceptable plant spacing, transplanting seedlings rather than broadcasting, avoiding water stress or long drained periods (flood as often as possible), and getting rid of crop residues. Change the planting date so that flowering does not fall in high humidity, and plant at the same time as your neighbours.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice blast, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_blast_252.htm', 'Management: cultural control', false),
  ('Blast', 'management_cultural', 'After harvest, collect and burn or bury the remains and stubble as soon as possible, and do not plant while the last crop is still in the ground.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice blast, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_blast_252.htm', 'Management: cultural control, after harvest', false),
  ('Blast', 'management_resistance', 'Resistant varieties have been bred against blast, but they may succumb to new strains of the fungus.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice blast, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_blast_252.htm', 'Management: resistant varieties', false),
  ('Blast', 'management_chemical', 'Smallholders rarely use fungicides against blast because of the expense and availability. For upland rice, seed treatment 1-2 days before sowing uses protectants (captan or mancozeb) or systemic products (pyroquilon, azoles, strobilurins). Check what is registered and available locally and follow the product label for dosage, timing and pre-harvest interval.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice blast, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_blast_252.htm', 'Management: chemical', false),
  ('Brown spot', 'favouring_conditions', 'Brown spot affects seedlings, leaves, leaf sheaths and panicles (glumes and seeds). It is worse in dryland than in wetland, especially under continuous cropping and low soil fertility. Low nitrogen, phosphorus and potassium, and perhaps low silica and manganese, are linked to the disease.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice brown leaf spot, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_brown_leaf_spot_427.htm', 'Symptoms & Life Cycle', false),
  ('Brown spot', 'favouring_conditions', 'Humidity above 85% for a few days, light rain, heavy dew and temperatures of 20-30 C favour brown spot.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice brown leaf spot, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_brown_leaf_spot_427.htm', 'Symptoms & Life Cycle', false),
  ('Brown spot', 'identification', 'On seedlings brown spot makes small, circular, yellow-brown or brown spots that girdle and distort the leaf sheaths. At tillering the spots are circular to oval, up to 10 mm long, dark brown to purple; mature spots have light brown to grey centres with dark brown margins.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice brown leaf spot, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_brown_leaf_spot_427.htm', 'Symptoms & Life Cycle', false),
  ('Brown spot', 'identification', 'On seeds, brown spot causes brown ''eye-spot'' marks with light centres, and infected seeds do not fill properly; black spore masses form on leaf and seed spots. The spots look like blast but appear later, are more regular in outline and have lighter centres.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice brown leaf spot, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_brown_leaf_spot_427.htm', 'Symptoms & Life Cycle, and Detection', false),
  ('Brown spot', 'survival_spread', 'Spores spread short distances by wind and longer distances on infected seed. The fungus survives in infected seed, volunteer rice, rice debris and wild grasses.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice brown leaf spot, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_brown_leaf_spot_427.htm', 'Symptoms & Life Cycle', false),
  ('Brown spot', 'impact', 'Brown spot is not considered as serious as blast. IRRI calculates a yield loss of 5% a year across South and Southeast Asia, with local losses of over 40%. Losses come from seedling death and from lower seed quality and weight.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice brown leaf spot, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_brown_leaf_spot_427.htm', 'Impact', false),
  ('Brown spot', 'management_cultural', 'Treat seed with hot water, 53-54 C for 10-12 minutes, before planting. Apply fertilizer at the recommended rates. After harvest, collect the straw and debris and burn it with the stubble, or plough it into the soil. Use resistant varieties and check with local extension staff which suit your area.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice brown leaf spot, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_brown_leaf_spot_427.htm', 'Management: cultural control', false),
  ('Brown spot', 'management_chemical', 'Consider fungicides only after checking for a nutrient deficiency and whether resistant varieties are available. IRRI recommends seed treatments with iprodione, strobilurins (azoxystrobin or trifloxystrobin), an azole (propiconazole) or carbendazim. Sprays on the leaves at tillering and late boot stage are effective only if combined with a seed treatment.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice brown leaf spot, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_brown_leaf_spot_427.htm', 'Management: chemical', false),
  ('Bacterial leaf blight', 'identification', 'The bacteria enter the plant through natural openings and wounds, move in the water-conducting vessels (xylem) and block them. In older plants, pale yellow streaks with wavy margins run from the leaf tips toward the base and the leaves dry and die. Infection as late as booting does not affect yield but reduces grain quality. Streaks may also appear on sheaths and stems of susceptible varieties.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice bacterial leaf blight, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_bacterial_leaf_blight_418.htm', 'Symptoms & Life Cycle', false),
  ('Bacterial leaf blight', 'identification', 'Wavy margins on the streaks distinguish bacterial leaf blight from bacterial leaf streak, which has straight margins. In a cut-leaf test, cloudy liquid streams from the cut end of a leaf held in water. The disease can be mistaken for stem borer damage.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice bacterial leaf blight, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_bacterial_leaf_blight_418.htm', 'Detection and inspection', false),
  ('Bacterial leaf blight', 'favouring_conditions', 'Warm, humid weather favours bacterial leaf blight: temperatures of 25-34 C and relative humidity above 70%. Too much nitrogen increases humidity inside the crop and increases the disease.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice bacterial leaf blight, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_bacterial_leaf_blight_418.htm', 'Symptoms & Life Cycle, and Cultural control', false),
  ('Bacterial leaf blight', 'survival_spread', 'Within a crop the bacteria spread in irrigation and flood water and by wind-driven rain; over longer distances they probably travel on seed. How the bacteria survive between crops is not well understood, but probably in seed. They survive about a month in dryland soil or plant remains, perhaps half as long when submerged, and longer on weeds.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice bacterial leaf blight, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_bacterial_leaf_blight_418.htm', 'Spread and survival', false),
  ('Bacterial leaf blight', 'hosts', 'Besides rice, the bacterium lives on wild grasses, especially rice cutgrass (Leersia species).', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice bacterial leaf blight, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_bacterial_leaf_blight_418.htm', 'Hosts', false),
  ('Bacterial leaf blight', 'impact', 'Bacterial leaf blight can be devastating if infection is early. Yield losses of 20% to more than 70% have been reported in Southeast Asia and India. In the Philippines, losses were more than 20% on susceptible varieties in the wet season and 7% in the dry season.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice bacterial leaf blight, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_bacterial_leaf_blight_418.htm', 'Impact', false),
  ('Bacterial leaf blight', 'management_cultural', 'Choose seed from uninfected plants. When lifting seedlings keep the roots intact and do not clip the leaves. Keep weeds, especially Leersia, under control. Make sure fields can drain, because most varieties cannot withstand flooding for more than a week. After harvest, plough to bury stubble, straw, ratoon and volunteer plants, and let fallow fields dry.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice bacterial leaf blight, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_bacterial_leaf_blight_418.htm', 'Management: cultural control', false),
  ('Bacterial leaf blight', 'management_cultural', 'Too much nitrogen increases humidity and disease; a suggested amount is 80-100 kg N/ha, depending on local conditions.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice bacterial leaf blight, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_bacterial_leaf_blight_418.htm', 'Management: cultural control', false),
  ('Bacterial leaf blight', 'management_resistance', 'In low-input systems, resistant or tolerant varieties plus good weed control are the main approach. Check which resistant varieties are available locally.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice bacterial leaf blight, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_bacterial_leaf_blight_418.htm', 'Management: cultural control, resistant varieties', false),
  ('Bacterial leaf blight', 'management_chemical', 'Copper compounds and antibiotics are costly and have not been shown to be effective against bacterial leaf blight.', 'Pacific Pests, Pathogens and Weeds (online edition v10), Rice bacterial leaf blight, Grahame Jackson, 2021', 'https://apps.lucidcentral.org/pppw_v10/text/web_full/entities/rice_bacterial_leaf_blight_418.htm', 'Management: chemical', false);
